// Tiêm CSS/font v2 khi skin được nạp (an toàn gọi nhiều lần).
injectV2Styles();

// Đăng ký bộ bề mặt overlay (bản đồ cộng đồng / trình dựng tư thế / hướng dẫn cách chơi): card trắng
